sitive"},"id":"kinship_reference"},{"body":[{"arguments":[{"var":"K"},{"var":"Cue"},{"var":"Bearer"},{"var":"Reference"},{"var":"Start"},{"var":"End"}],"predicate":"kinship_source","sign":"positive"}],"cost":1,"head":{"arguments":[{"var":"K"},{"var":"Start"}],"predicate":"start_","sign":"positive"},"id":"kinship_start"},{"body":[{"arguments":[{"var":"K"},{"var":"Cue"},{"var":"Bearer"},{"var":"Reference"},{"var":"Start"},{"var":"End"}],"predicate":"kinship_source","sign":"positive"}],"cost":1,"head":{"arguments":[{"var":"K"},{"var":"End"}],"predicate":"end_","sign":"positive"},"id":"kinship_end"}],"read_constraint_program":"def apply(inputs, premises):
    unread = {'status':'unread','domains':[],'witnesses':[]}
    facts = inputs.get('facts')
    fields = inputs.get('record_fields')
    if not isinstance(facts, str) or not facts.strip() or not isinstance(fields, list):
        return unread
    date_names = []
    for field in fields:
        if isinstance(field, dict):
            name = field.get('name')
            if name in ('start', 'end') and field.get('nullable') is True:
                date_names.append(name)
    if not date_names:
        return unread
    text = facts.strip()
    cue_pattern = '(?i)(?<![A-Za-z])(?:son|daughter|father|mother|brother|sister|sibling)(?![A-Za-z])'
    possessor = '(?:his|her|their|[A-Z][A-Za-z-]*(?:' + chr(39) + 's|’s))'
    role_pattern = '(?i)(?<![A-Za-z])' + possessor + '[ ]+(son|daughter|father|mother|brother|sister|sibling)[ ]+[A-Z][A-Za-z-]*(?![A-Za-z])'
    cue_matches = list(re.finditer(cue_pattern, text))
    role_matches = list(re.finditer(role_pattern, text))
    if not role_matches or len(cue_matches) != len(role_matches):
        return unread
    cue_positions = []
    role_positions = []
    for match in cue_matches:
        cue_positions.append(match.start())
    for match in role_matches:
        role_positions.append(match.start(1))
    if cue_positions != role_positions:
        return unread
    month = '(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Sept|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)'
    date_pattern = '(?i)(?<![A-Za-z])' + month + '[.]?[ ]+[0-9]{1,2}(?:st|nd|rd|th)?(?:,[ ]*|[ ]+)[0-9]{4}(?![0-9])|(?<![0-9])[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}(?![0-9])|(?<![0-9])[0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4}(?![0-9])|(?<![0-9$])(?:18|19|20|21)[0-9]{2}(?![0-9])'
    dates = list(re.finditer(date_pattern, text))
    signal_pattern = '(?i)(?<![A-Za-z])(?:from|since|until|between|during|before|after)(?![A-Za-z])'
    signals = list(re.finditer(signal_pattern, text))
    if signals and not dates:
        return unread
    event_pattern = '(?i)(?<![A-Za-z])(?:work|worked|working|service|employment|employed|residence|resided|residing|lived|living|marriage|married|wedding|birth|born)(?![A-Za-z])[^.!?;]{0,160}?(?<![A-Za-z])(?:from|between|since|during|on|in)(?![A-Za-z])'
    anchors = list(re.finditer(event_pattern, text))
    for date in dates:
        left = 0
        for mark in '.!?;':
            position = text.rfind(mark, 0, date.start())
            if position + 1 > left:
                left = position + 1
        attached = False
        for anchor in anchors:
            if anchor.start() >= left and anchor.end() <= date.start():
                attached = True
        if not attached:
            return unread
    for signal in signals:
        right = len(text)
        for mark in '.!?;':
            position = text.find(mark, signal.end())
            if position >= 0 and position < right:
                right = position
        supported = False
        for date in dates:
            if date.start() >= signal.end() and date.start() <= right and date.start() - signal.end() <= 180:
                supported = True
        if not supported:
            return unread
    domains = []
    for name in date_names:
        domains.append({'field':name,'values':[None]})
    return {'status':'constrained','domains':domains,'witnesses':[{'field':'facts','quote':facts}]}"}
